import "core-js/modules/es6.function.name";
import "core-js/modules/es6.array.find";
import { getList as _getList, enumAll, getEnumValues, getDictList } from "@/api/safeDanger/glDevice";
export default {
  name: "deviceTable",
  components: {},
  props: {},
  data: function data() {
    return {
      queryParams: {
        pageNum: 1,
        pageSize: 20,
        ciId: '1097755012694017',
        //默认IT设备
        attrCode: 'deviceCode,deviceName'
      },
      // 总条数
      total: 0,
      options: [],
      tableList: [],
      tableHeight: undefined,
      loading: false,
      ciIdList: [],
      deviceCategoryList: null,
      deviceTypeList: null,
      deviceSourceList: null,
      makerList: null,
      brandList: null,
      seriesList: null,
      deviceModelList: null
    };
  },
  watch: {
    'queryParams.deviceCategory': function queryParamsDeviceCategory(newVal, oldVal) {
      if (!this.isEmpty(newVal)) {
        //加载设备类型
        this.getCmdbDictListPid(this.ciIdList.find(function (a) {
          return a.name == 'deviceType';
        }), newVal);
      }
      this.deviceTypeList = null;
      if (!this.isEmpty(this.queryParams.deviceType)) {
        this.queryParams.deviceType = null;
      }
    },
    'queryParams.maker': function queryParamsMaker(newVal, oldVal) {
      if (!this.isEmpty(newVal)) {
        //加载品牌
        this.getCmdbDictListPid(this.ciIdList.find(function (a) {
          return a.name == 'brand';
        }), newVal);
      }
      //初始化品牌、系列、型号
      this.brandList = null;
      this.seriesList = null;
      this.deviceModelList = null;
      if (!this.isEmpty(this.queryParams.brand)) {
        this.queryParams.brand = null;
      }
      if (!this.isEmpty(this.queryParams.series)) {
        this.queryParams.series = null;
      }
      if (!this.isEmpty(this.queryParams.deviceModel)) {
        this.queryParams.deviceModel = null;
      }
    },
    'queryParams.brand': function queryParamsBrand(newVal, oldVal) {
      if (!this.isEmpty(newVal)) {
        //加载系列
        this.getCmdbDictListPid(this.ciIdList.find(function (a) {
          return a.name == 'series';
        }), newVal);
      }
      //初始化系列、型号
      this.seriesList = null;
      this.deviceModelList = null;
      if (!this.isEmpty(this.queryParams.series)) {
        this.queryParams.series = null;
      }
      if (!this.isEmpty(this.queryParams.deviceModel)) {
        this.queryParams.deviceModel = null;
      }
    },
    'queryParams.series': function queryParamsSeries(newVal, oldVal) {
      if (!this.isEmpty(newVal)) {
        //加载型号
        this.getCmdbDictListPid(this.ciIdList.find(function (a) {
          return a.name == 'deviceModel';
        }), newVal);
      }
      if (this.formValue.disposeStatus == 0) {
        //初始化型号
        this.deviceModelList = null;
        if (!this.isEmpty(this.queryParams.deviceModel)) {
          this.queryParams.deviceModel = null;
        }
      }
    }
  },
  mounted: function mounted() {
    var _this = this;
    //获取字典
    enumAll().then(function (res) {
      var list = res.data;
      if (list) {
        var props = [{
          name: 'deviceCategory',
          label: '设备分类'
        }, {
          name: 'deviceType',
          label: '设备类型',
          loading: false
        }, {
          name: 'deviceSource',
          label: '设备来源'
        }, {
          name: 'maker',
          label: '制造商'
        }, {
          name: 'brand',
          label: '品牌',
          loading: false
        }, {
          name: 'series',
          label: '系列',
          loading: false
        }, {
          name: 'deviceModel',
          label: '型号',
          loading: false
        }];
        props.forEach(function (item) {
          var fItem = list.find(function (a) {
            return a.enumCiAlias == item.label;
          });
          if (fItem) {
            _this.ciIdList.push({
              name: item.name,
              label: item.label,
              enumCiId: fItem.enumCiId,
              loading: item.loading
            });
          }
        });
      }
      //加载字典
      for (var i = 0; i < _this.ciIdList.length; i++) {
        var item = _this.ciIdList[i];
        if (item.loading != false) {
          _this.getCmdbDictList(item);
        }
      }
    });
    this.getCurrentHeight();
    this.getList();
  },
  methods: {
    getList: function getList() {
      var _this2 = this;
      this.loading = true;
      _getList(this.queryParams).then(function (response) {
        _this2.tableList = response.rows;
        _this2.total = response.total;
      }).finally(function () {
        _this2.loading = false;
      });
    },
    handleQuery: function handleQuery() {},
    resetQuery: function resetQuery() {
      this.queryParams = {
        pageNum: 1,
        pageSize: 20
      };
      this.total = 0;
      this.getList();
    },
    getCmdbDictList: function getCmdbDictList(item) {
      var _this3 = this;
      if (!item) {
        return;
      }
      getEnumValues(item.enumCiId).then(function (res) {
        if (item.name === 'deviceCategory') {
          // 设备分类
          _this3.deviceCategoryList = res.data;
        } else if (item.name === 'deviceSource') {
          // 设备来源
          _this3.deviceSourceList = res.data;
        } else if (item.name === 'maker') {
          // 制造商
          _this3.makerList = res.data;
        }
      });
    },
    getCmdbDictListPid: function getCmdbDictListPid(item, pid) {
      var _this4 = this;
      getDictList({
        ciId: item.enumCiId,
        cientityPid: pid
      }).then(function (res) {
        if (item.name === 'deviceType') {
          //设备类型
          _this4.deviceTypeList = res.data;
        } else if (item.name === 'brand') {
          //品牌
          _this4.brandList = res.data;
        } else if (item.name === 'series') {
          //系列
          _this4.seriesList = res.data;
        } else if (item.name === 'deviceModel') {
          //型号
          _this4.deviceModelList = res.data;
        }
      });
    },
    getPlaceholder: function getPlaceholder(list, params) {
      if (params && this.isEmpty(params.name)) {
        return "\u8BF7\u5148\u9009\u62E9".concat(params.label);
      }
      return list == null ? '加载中' : '请选择';
    },
    getDisabled: function getDisabled(list, params) {
      if (params) {
        if (this.isEmpty(params.name)) {
          return true;
        } else {
          return list == null ? true : false;
        }
      }
      return list == null ? true : false;
    },
    isEmpty: function isEmpty(value) {
      if (value == null || value === '') {
        return true;
      }
      return false;
    },
    // 获取自适应高度
    getCurrentHeight: function getCurrentHeight() {
      var windowHeight = window.innerHeight; //窗口高度
      this.tableHeight = windowHeight - 690 + 'px';
    }
  }
};
